def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, remaining_qty)
    sell_book = []  # List of (price, arrival_time, id, remaining_qty)
    order_map = {}  # id -> (side, price, arrival_time, index_in_book)
    arrival_counter = 0

    for order in orders:
        arrival_counter += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, arrival_time, book_index = order_map[order_id]
                if side == 'buy':
                    if book_index < len(buy_book) and buy_book[book_index][2] == order_id:
                        buy_book[book_index] = (price, arrival_time, order_id, 0)
                elif side == 'sell':
                    if book_index < len(sell_book) and sell_book[book_index][2] == order_id:
                        sell_book[book_index] = (price, arrival_time, order_id, 0)
                del order_map[order_id]

        elif order[0] in ['limit', 'ioc', 'market']:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = None if order_type == 'market' else order[3]

            order_map[order_id] = (side, price, arrival_counter, -1)

            if side == 'buy':
                # Match against sell_book
                while qty > 0 and sell_book:
                    # Remove cancelled entries
                    while sell_book and sell_book[0][3] == 0:
                        sell_book.pop(0)

                    if not sell_book:
                        break

                    resting_price, resting_arrival, resting_id, resting_qty = sell_book[0]

                    if price is not None and resting_price > price:
                        break

                    trade_qty = min(qty, resting_qty)
                    trades.append([order_id, resting_id, resting_price, trade_qty])

                    qty -= trade_qty
                    resting_qty -= trade_qty

                    if resting_qty == 0:
                        sell_book.pop(0)
                    else:
                        sell_book[0] = (resting_price, resting_arrival, resting_id, resting_qty)

                # Add remaining to buy_book if limit order
                if qty > 0 and order_type == 'limit':
                    buy_book.append((price, arrival_counter, order_id, qty))
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    order_map[order_id] = (side, price, arrival_counter, buy_book.index((price, arrival_counter, order_id, qty)))

            else:  # side == 'sell'
                # Match against buy_book
                while qty > 0 and buy_book:
                    # Remove cancelled entries
                    while buy_book and buy_book[0][3] == 0:
                        buy_book.pop(0)

                    if not buy_book:
                        break

                    resting_price, resting_arrival, resting_id, resting_qty = buy_book[0]

                    if price is not None and resting_price < price:
                        break

                    trade_qty = min(qty, resting_qty)
                    trades.append([resting_id, order_id, resting_price, trade_qty])

                    qty -= trade_qty
                    resting_qty -= trade_qty

                    if resting_qty == 0:
                        buy_book.pop(0)
                    else:
                        buy_book[0] = (resting_price, resting_arrival, resting_id, resting_qty)

                # Add remaining to sell_book if limit order
                if qty > 0 and order_type == 'limit':
                    sell_book.append((price, arrival_counter, order_id, qty))
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    order_map[order_id] = (side, price, arrival_counter, sell_book.index((price, arrival_counter, order_id, qty)))

    return trades

